use vstd::prelude::*;

verus! {

    /// copy: Vec<u64> → Vec<u64>, preserving length and contents
    fn copy(a: &Vec<u64>) -> (b: Vec<u64>)
        ensures
            // The “@” operator projects a Vec<T> to the mathematical sequence Seq<T>
            b@ == a@,
    {
        // Pre‐allocate the new Vec with the same capacity as a.len()
        let mut b: Vec<u64> = Vec::with_capacity(a.len());
        // We'll walk through a by index so we can state a loop‐invariant
        let mut idx: usize = 0;

        // Invariant says:
        //   1) idx never exceeds a.len()
        //   2) b@ == a@[0..idx], i.e. b contains exactly the first idx elements of a
        // And we show termination by decreasing (a.len() - idx).
        while idx < a.len()
            invariant
                idx <= a.len(),
                b@ == a@[..idx],
            decreases
                a.len() - idx,
        {
            // Read the current element
            let val: u64 = a[idx];
            // Push it onto b
            b.push(val);
            // Advance
            idx += 1;
        }

        // At loop exit we know idx == a.len(), so b@ == a@[..a.len()] == a@
        b
    }

} // end of verus!

fn main() {
    let original = vec![10, 20, 30, 40];
    let cloned   = copy(&original);
    assert_eq!(original, cloned);
    println!("Original: {:?}, Cloned: {:?}", original, cloned);
}